"use client";

import { useEffect, useRef } from "react";
import createGlobe from "cobe";

/* New Delhi coords → cobe uses [lat, long] in radians internally,
   but the markers API accepts degrees. We convert below. */
const DELHI_LAT = 28.6139;
const DELHI_LNG = 77.209;

export function CobeGlobe() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pointerDown = useRef(false);
  const pointerX = useRef(0);
  const phi = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let width = 0;

    const onResize = () => {
      if (canvas.parentElement) {
        width = canvas.parentElement.clientWidth;
      }
    };
    onResize();
    window.addEventListener("resize", onResize);

    const globe = createGlobe(canvas, {
      devicePixelRatio: Math.min(window.devicePixelRatio, 2),
      width: width * 2,
      height: width * 2,
      phi: 0,
      theta: 0.25,
      dark: 1,
      diffuse: 1.2,
      mapSamples: 20000,
      mapBrightness: 2.5,
      baseColor: [0.15, 0.15, 0.15],
      markerColor: [1, 0.27, 0], // #FF4500 → [1, 69/255, 0]
      glowColor: [0.08, 0.08, 0.08],
      markers: [{ location: [DELHI_LAT, DELHI_LNG], size: 0.08 }],
      onRender: (state) => {
        // Auto-rotate unless the user is dragging
        if (!pointerDown.current) {
          phi.current += 0.003;
        }
        state.phi = phi.current;
        state.width = width * 2;
        state.height = width * 2;
      },
    });

    // Drag interaction
    const onPointerDown = (e: PointerEvent) => {
      pointerDown.current = true;
      pointerX.current = e.clientX;
    };
    const onPointerUp = () => {
      pointerDown.current = false;
    };
    const onPointerMove = (e: PointerEvent) => {
      if (pointerDown.current) {
        const delta = e.clientX - pointerX.current;
        pointerX.current = e.clientX;
        phi.current += delta / 200;
      }
    };

    canvas.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointermove", onPointerMove);

    return () => {
      globe.destroy();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointermove", onPointerMove);
    };
  }, []);

  return (
    <div
      style={{
        width: "100%",
        maxWidth: "420px",
        aspectRatio: "1",
        margin: "0 auto",
        position: "relative",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
          cursor: "grab",
          contain: "layout paint size",
        }}
      />
    </div>
  );
}
